// Задание 1: Реле температуры на основе аналогового датчика LM35
const int lm35Pin = A4;   // Вход для аналогового датчика LM35
const int relayPin = 12;  // Выход для реле
const int thresholdTemp = 70; // Пороговая температура 70 °C

void setup() {
  Serial.begin(9600);
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW); // Реле изначально выключено
  Serial.println("Система контроля температуры LM35 запущена.");
}

void loop() {
  // Чтение значений с аналогового входа (0-1023)
  int sensorValue = analogRead(lm35Pin);

  // Конвертация в напряжение (5V / 1024) и вычисление температуры
  // LM35 выдает 10 мВ на 1 градус Цельсия, поэтому умножаем на 100
  float voltage = sensorValue * (5.0 / 1024.0);
  float temperature = voltage * 100.0;

  Serial.print("Температура: ");
  Serial.print(temperature);
  Serial.println(" °C");

  // Проверка условия срабатывания реле
  if (temperature >= thresholdTemp) {
    digitalWrite(relayPin, HIGH);
    Serial.println("ВНИМАНИЕ: Превышение температуры! Реле ВКЛ.");
  } else {
    digitalWrite(relayPin, LOW);
  }

  delay(1000); // Задержка для стабильности чтения
}
